        # Numbers starting with 1: 1XXXX... (n-1 X's) -> 10^(n-1) possibilities
        # Numbers ending with 1: XXXX...1 (n-1 X's) -> 9 * 10^(n-2) possibilities (first digit cannot be 0)
        # Subtract the overlap where numbers both start and end with 1: 1XXX...1 -> 10^(n-2) possibilities
        return 10**(n-1) + 9 * 10**(n-2) - 10**(n-2)

